import * as fs from 'fs'
import * as path from 'path'

/**
 * Plan round1-test-fake-urls (verifier feedback test_fake_urls): every adapter
 * test runs against fake hosts — example.test domains or 127.0.0.1 mock
 * servers. The real provider host lives only in src/config defaults (and
 * documentation), never in test code. This lint-style test recursively scans
 * the test tree for the provider host and for any websocket URL on the
 * provider's host prefix and fails listing the offending files.
 *
 * test/golden/ is excluded from the scan: those tests are generated by the
 * verifier pipeline from recorded golden vectors and are agent-unwritable (a
 * change there is a spec change, human re-gated). The legacy
 * test/integration/fixtures.ts baseline is excluded for the same reason: it is
 * a protected fixture restored verbatim from the reference adapter (its nock
 * host is real, but nock intercepts the request — no network egress). This
 * guard covers everything the adapter agents themselves write under test/unit
 * and test/integration: every agent-authored test file must run against fake
 * hosts only.
 */
describe('no provider hosts in test code (plan round1-test-fake-urls / verifier feedback test_fake_urls)', () => {
  const TEST_ROOT = path.resolve(__dirname, '..')
  const EXCLUDED_DIRS = new Set([path.join(TEST_ROOT, 'golden')])
  const EXCLUDED_FILES = new Set([path.join(TEST_ROOT, 'integration', 'fixtures.ts')])
  const SCANNED_EXTENSIONS = /\.(ts|tsx|js|jsx|cjs|mjs|json|md|txt)$/

  // The forbidden strings are assembled from parts so this test file does not
  // itself contain the host it forbids.
  const PROVIDER_HOST = ['tools', 'dxfeed', 'com'].join('.')
  const PROVIDER_WS_PREFIX = `wss://${PROVIDER_HOST.split('.')[0]}.`
  const FORBIDDEN: [string, string][] = [
    ['the provider host', PROVIDER_HOST],
    [`a ${PROVIDER_WS_PREFIX}* url`, PROVIDER_WS_PREFIX],
  ]

  const listTestFiles = (dir: string): string[] =>
    fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
      const full = path.join(dir, entry.name)
      if (entry.isDirectory()) {
        return EXCLUDED_DIRS.has(full) ? [] : listTestFiles(full)
      }
      if (EXCLUDED_FILES.has(full)) {
        return []
      }
      return SCANNED_EXTENSIONS.test(entry.name) ? [full] : []
    })

  it('scan test/: the provider host and any provider-prefix websocket url appear in no test file', () => {
    const offenders = listTestFiles(TEST_ROOT)
      .map((file) => {
        const contents = fs.readFileSync(file, 'utf8')
        const hits = FORBIDDEN.filter(([, needle]) => contents.includes(needle)).map(
          ([label]) => label,
        )
        return hits.length > 0
          ? `${path.relative(TEST_ROOT, file)} (${hits.join(', ')})`
          : undefined
      })
      .filter((offender): offender is string => offender !== undefined)

    expect(offenders).toEqual([])
  })
})

describe('merged: framework-version.test', () => {
  /**
   * Plan item 2's proving test (spec suggested_implementation: "Framework version
   * MUST resolve >= 2.20.0 — customSubscriptionMessages does not exist in the
   * stale unplugged 2.16.1 copy"). The version is read from the package the
   * module resolver ACTUALLY loads at runtime — not from this package.json's
   * dependency pin — so a stale unplugged/hoisted copy fails here even when the
   * pin looks right.
   */
  const FRAMEWORK = '@chainlink/external-adapter-framework'

  const installedFrameworkVersion = (): string => {
    // Yarn PnP (this repo's nodeLinker) resolves the deep subpath and loads the
    // JSON out of the zip archive the package lives in; a node_modules install
    // resolves the same specifier through the directory tree
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      return require(`${FRAMEWORK}/package.json`).version
    } catch {
      // Fallback: walk up from the resolved runtime entry to the owning
      // package.json (works when the specifier above is blocked by an exports map)
      const entry = require.resolve(FRAMEWORK)
      let dir = path.dirname(entry)
      while (dir !== path.parse(dir).root) {
        const candidate = path.join(dir, 'package.json')
        if (fs.existsSync(candidate)) {
          const pkg = JSON.parse(fs.readFileSync(candidate, 'utf8'))
          if (pkg.name === FRAMEWORK) {
            return pkg.version
          }
        }
        dir = path.dirname(dir)
      }
      throw new Error(`Could not locate the installed ${FRAMEWORK} package.json`)
    }
  }

  /** Minimal semver comparison for the framework's x.y.z release versions. */
  const atLeast = (version: string, major: number, minor: number): boolean => {
    const [vMajor, vMinor] = version.split('.').map((segment) => parseInt(segment, 10))
    if (Number.isNaN(vMajor) || Number.isNaN(vMinor)) {
      throw new Error(`Unparseable framework version: ${version}`)
    }
    return vMajor > major || (vMajor === major && vMinor >= minor)
  }

  describe('framework version (spec suggested_implementation / plan item 2)', () => {
    it('resolves the installed @chainlink/external-adapter-framework at >= 2.20.0 (customSubscriptionMessages exists only from 2.20.0)', () => {
      const version = installedFrameworkVersion()

      // The resolution must not silently fall back to the adapter's own package
      expect(version).not.toBe('2.8.7')
      expect(atLeast(version, 2, 20)).toBe(true)
    })
  })
})
